-- No online custom-role assignments or approval chains existed in this snapshot.

CREATE TEMP TABLE import_user_id_map (
  source_id uuid PRIMARY KEY,
  target_id uuid NOT NULL UNIQUE
) ON COMMIT DROP;

-- Match by User ID first, then case-insensitive email; otherwise retain source UUID.
INSERT INTO import_user_id_map(source_id, target_id)
SELECT iu.id,
       COALESCE(
         (SELECT p.id
            FROM import_profiles ip
            JOIN public.profiles p ON lower(p.username) = lower(ip.username)
           WHERE ip.id = iu.id AND NULLIF(btrim(ip.username), '') IS NOT NULL
           LIMIT 1),
         (SELECT u.id FROM auth.users u WHERE lower(u.email) = lower(iu.email) LIMIT 1),
         iu.id
       )
FROM import_users iu;

DO $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM import_users iu
    JOIN import_user_id_map m ON m.source_id=iu.id
    JOIN auth.users u ON lower(u.email)=lower(iu.email)
    WHERE u.id <> m.target_id
  ) THEN
    RAISE EXCEPTION 'Unsafe User ID/email collision detected; transaction cancelled';
  END IF;
END $$;

INSERT INTO auth.users (id,instance_id,aud,role,email,encrypted_password,email_confirmed_at,invited_at,confirmation_token,confirmation_sent_at,recovery_token,recovery_sent_at,email_change_token_new,email_change,email_change_sent_at,last_sign_in_at,raw_app_meta_data,raw_user_meta_data,is_super_admin,created_at,updated_at,phone,phone_confirmed_at,phone_change,phone_change_token,phone_change_sent_at,email_change_token_current,email_change_confirm_status,banned_until,reauthentication_token,reauthentication_sent_at,is_sso_user,deleted_at,is_anonymous)
SELECT iu.id,iu.instance_id,iu.aud,iu.role,iu.email,iu.encrypted_password,iu.email_confirmed_at,iu.invited_at,iu.confirmation_token,iu.confirmation_sent_at,iu.recovery_token,iu.recovery_sent_at,iu.email_change_token_new,iu.email_change,iu.email_change_sent_at,iu.last_sign_in_at,iu.raw_app_meta_data,iu.raw_user_meta_data,iu.is_super_admin,iu.created_at,iu.updated_at,iu.phone,iu.phone_confirmed_at,iu.phone_change,iu.phone_change_token,iu.phone_change_sent_at,iu.email_change_token_current,iu.email_change_confirm_status,iu.banned_until,iu.reauthentication_token,iu.reauthentication_sent_at,iu.is_sso_user,iu.deleted_at,iu.is_anonymous
FROM import_users iu JOIN import_user_id_map m ON m.source_id=iu.id
WHERE m.target_id=iu.id
AND NOT EXISTS (SELECT 1 FROM auth.users u WHERE u.id=iu.id OR lower(u.email)=lower(iu.email));

UPDATE auth.users u SET
 instance_id=iu.instance_id,aud=iu.aud,role=iu.role,email=iu.email,
 encrypted_password=iu.encrypted_password,email_confirmed_at=iu.email_confirmed_at,
 invited_at=iu.invited_at,confirmation_token=iu.confirmation_token,
 confirmation_sent_at=iu.confirmation_sent_at,recovery_token=iu.recovery_token,
 recovery_sent_at=iu.recovery_sent_at,email_change_token_new=iu.email_change_token_new,
 email_change=iu.email_change,email_change_sent_at=iu.email_change_sent_at,
 raw_app_meta_data=iu.raw_app_meta_data,raw_user_meta_data=iu.raw_user_meta_data,
 is_super_admin=iu.is_super_admin,phone=iu.phone,phone_confirmed_at=iu.phone_confirmed_at,
 phone_change=iu.phone_change,phone_change_token=iu.phone_change_token,
 phone_change_sent_at=iu.phone_change_sent_at,email_change_token_current=iu.email_change_token_current,
 email_change_confirm_status=iu.email_change_confirm_status,banned_until=iu.banned_until,
 reauthentication_token=iu.reauthentication_token,
 reauthentication_sent_at=iu.reauthentication_sent_at,is_sso_user=iu.is_sso_user,
 deleted_at=iu.deleted_at,is_anonymous=iu.is_anonymous,updated_at=greatest(u.updated_at,iu.updated_at)
FROM import_users iu JOIN import_user_id_map m ON m.source_id=iu.id
WHERE u.id=m.target_id;

INSERT INTO auth.identities (id,user_id,identity_data,provider,provider_id,last_sign_in_at,created_at,updated_at)
SELECT ii.id,m.target_id,
 jsonb_set(COALESCE(ii.identity_data,'{}'::jsonb),'{sub}',to_jsonb(m.target_id::text),true),
 ii.provider,CASE WHEN ii.provider_id=ii.user_id::text THEN m.target_id::text ELSE ii.provider_id END,
 ii.last_sign_in_at,ii.created_at,ii.updated_at
FROM import_identities ii JOIN import_user_id_map m ON m.source_id=ii.user_id
ON CONFLICT (provider_id,provider) DO UPDATE SET
 user_id=EXCLUDED.user_id,identity_data=EXCLUDED.identity_data,
 last_sign_in_at=greatest(auth.identities.last_sign_in_at,EXCLUDED.last_sign_in_at),
 updated_at=greatest(auth.identities.updated_at,EXCLUDED.updated_at);

INSERT INTO public.app_role_def (key,name,description,is_system,created_at,updated_at)
SELECT key,name,description,is_system,created_at,updated_at FROM import_role_defs
ON CONFLICT (key) DO UPDATE SET name=EXCLUDED.name,description=EXCLUDED.description,
 is_system=EXCLUDED.is_system,updated_at=EXCLUDED.updated_at;

INSERT INTO public.profiles (id,email,full_name,created_at,is_active,username,employee_id,department,first_name,last_name,contact,status,company_code)
SELECT m.target_id,p.email,p.full_name,p.created_at,p.is_active,p.username,p.employee_id,p.department,
 p.first_name,p.last_name,p.contact,p.status,p.company_code
FROM import_profiles p JOIN import_user_id_map m ON m.source_id=p.id
ON CONFLICT (id) DO UPDATE SET email=EXCLUDED.email,full_name=EXCLUDED.full_name,
 is_active=EXCLUDED.is_active,username=EXCLUDED.username,employee_id=EXCLUDED.employee_id,
 department=EXCLUDED.department,first_name=EXCLUDED.first_name,last_name=EXCLUDED.last_name,
 contact=EXCLUDED.contact,status=EXCLUDED.status,company_code=EXCLUDED.company_code;

INSERT INTO public.user_roles (user_id,role,created_at)
SELECT m.target_id,r.role,r.created_at FROM import_user_roles r
JOIN import_user_id_map m ON m.source_id=r.user_id
ON CONFLICT (user_id,role) DO UPDATE SET created_at=EXCLUDED.created_at;

INSERT INTO public.user_role_assignment (user_id,role_key,created_at)
SELECT m.target_id,a.role_key,a.created_at FROM import_assignments a
JOIN import_user_id_map m ON m.source_id=a.user_id
ON CONFLICT (user_id,role_key) DO UPDATE SET created_at=EXCLUDED.created_at;

INSERT INTO public.role_permission (role,screen,allowed,created_at,updated_at,role_key)
SELECT role,screen,allowed,created_at,updated_at,role_key FROM import_permissions
ON CONFLICT (role_key,screen) DO UPDATE SET role=EXCLUDED.role,allowed=EXCLUDED.allowed,
 updated_at=EXCLUDED.updated_at;

INSERT INTO public.approval_chain (id,name,owner_user_id,role_key,is_active,created_by,created_at,updated_at)
SELECT c.id,c.name,owner.target_id,c.role_key,c.is_active,creator.target_id,c.created_at,c.updated_at
FROM import_chains c
LEFT JOIN import_user_id_map owner ON owner.source_id=c.owner_user_id
LEFT JOIN import_user_id_map creator ON creator.source_id=c.created_by
ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name,owner_user_id=EXCLUDED.owner_user_id,
 role_key=EXCLUDED.role_key,is_active=EXCLUDED.is_active,created_by=EXCLUDED.created_by,
 updated_at=EXCLUDED.updated_at;

INSERT INTO public.approval_chain_level (chain_id,level,approver_id,designation,created_at)
SELECT l.chain_id,l.level,m.target_id,l.designation,l.created_at
FROM import_chain_levels l JOIN import_user_id_map m ON m.source_id=l.approver_id
ON CONFLICT (chain_id,level) DO UPDATE SET approver_id=EXCLUDED.approver_id,
 designation=EXCLUDED.designation;

ALTER TABLE auth.users ENABLE TRIGGER on_auth_user_created;

DO $$
DECLARE expected_count integer; actual_count integer;
BEGIN
 SELECT count(*) INTO expected_count FROM import_users;
 SELECT count(*) INTO actual_count FROM import_user_id_map m JOIN public.profiles p ON p.id=m.target_id;
 IF actual_count <> expected_count THEN
   RAISE EXCEPTION 'Profile verification failed: expected %, found %',expected_count,actual_count;
 END IF;
 SELECT count(*) INTO expected_count FROM import_identities;
 SELECT count(*) INTO actual_count FROM import_identities i
 JOIN import_user_id_map m ON m.source_id=i.user_id
 JOIN auth.identities ai ON ai.user_id=m.target_id AND ai.provider=i.provider;
 IF actual_count <> expected_count THEN
   RAISE EXCEPTION 'Identity verification failed: expected %, found %',expected_count,actual_count;
 END IF;
END $$;

COMMIT;
